const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1], e = tok[2];
const adj = Array.from({ length: n + 1 }, () => []);
for (let i = 0; i < e; i++) adj[tok[3 + 2 * i]].push(tok[4 + 2 * i]);
const match = new Array(m + 1).fill(0);
let seen;
function tryAugment(u) {
  for (const v of adj[u]) {
    if (!seen[v]) {
      seen[v] = true;
      if (match[v] === 0 || tryAugment(match[v])) { match[v] = u; return true; }
    }
  }
  return false;
}
let result = 0;
for (let u = 1; u <= n; u++) {
  seen = new Array(m + 1).fill(false);
  if (tryAugment(u)) result++;
}
console.log(String(result));

