import java.io.*;
import java.util.*;

public class Main {
    static List<Integer>[] adj;
    static int[] match;
    static boolean[] seen;

    static boolean tryAugment(int u) {
        for (int v : adj[u]) {
            if (!seen[v]) {
                seen[v] = true;
                if (match[v] == 0 || tryAugment(match[v])) { match[v] = u; return true; }
            }
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        in.nextToken();
        int e = (int) in.nval;
        adj = new List[n + 1];
        for (int i = 0; i <= n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < e; i++) {
            in.nextToken();
            int u = (int) in.nval;
            in.nextToken();
            adj[u].add((int) in.nval);
        }
        match = new int[m + 1];
        int result = 0;
        for (int u = 1; u <= n; u++) {
            seen = new boolean[m + 1];
            if (tryAugment(u)) result++;
        }
        System.out.println(result);
    }
}

