#include <bits/stdc++.h>
using namespace std;
vector<vector<int>> adj;
vector<int> match_;
vector<bool> seen;

bool tryAugment(int u) {
    for (int v : adj[u]) {
        if (!seen[v]) {
            seen[v] = true;
            if (match_[v] == 0 || tryAugment(match_[v])) { match_[v] = u; return true; }
        }
    }
    return false;
}

int main() {
    int n, m, e;
    scanf("%d %d %d", &n, &m, &e);
    adj.assign(n + 1, {});
    for (int i = 0; i < e; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u].push_back(v);
    }
    match_.assign(m + 1, 0);
    int result = 0;
    for (int u = 1; u <= n; u++) {
        seen.assign(m + 1, false);
        if (tryAugment(u)) result++;
    }
    printf("%d\n", result);
    return 0;
}
